'use strict';

/**
 * LocalPass - On-disk storage primitives
 *
 * Pure Node: no Electron import, so the whole module is testable without a
 * running app and the main process stays the only place that knows real paths.
 * The renderer never sends a path; it sends a payload and the main process
 * derives where it goes.
 */

const fs = require('fs');
const path = require('path');

const VAULT_FILE = 'vault.enc.json';
const SETTINGS_FILE = 'settings.json';

/** A vault with 5,000 accounts stays well under this. */
const MAX_STORED_BYTES = 5 * 1024 * 1024;

/** Device ids are generated by the app (`crypto.randomUUID()`). */
const DEVICE_ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;
const CHANGE_LOG_PATTERN = /^changes-([A-Za-z0-9_-]{1,64})\.enc\.json$/;

class StorageError extends Error {
  constructor(code) {
    super(code);
    this.name = 'StorageError';
    this.code = code;
  }
}

function vaultPath(dataDir) {
  return path.join(dataDir, VAULT_FILE);
}

function settingsPath(dataDir) {
  return path.join(dataDir, SETTINGS_FILE);
}

function assertDeviceId(deviceId) {
  if (typeof deviceId !== 'string' || !DEVICE_ID_PATTERN.test(deviceId)) {
    throw new StorageError('invalid_argument');
  }
  return deviceId;
}

function syncLogPath(syncDir, deviceId) {
  assertDeviceId(deviceId);
  return path.join(syncDir, `changes-${deviceId}.enc.json`);
}

/**
 * The renderer is not trusted with anything but a serialized envelope. A size
 * cap and a JSON check reject a runaway write before it can touch the disk.
 */
function assertPayload(payload) {
  if (typeof payload !== 'string') throw new StorageError('invalid_argument');
  if (Buffer.byteLength(payload, 'utf8') > MAX_STORED_BYTES) {
    throw new StorageError('payload_too_large');
  }

  let parsed;
  try {
    parsed = JSON.parse(payload);
  } catch {
    throw new StorageError('invalid_argument');
  }

  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
    throw new StorageError('invalid_argument');
  }

  return payload;
}

/** Synchronous sleep; only used between rename retries. */
function sleepSync(ms) {
  const shared = new SharedArrayBuffer(4);
  Atomics.wait(new Int32Array(shared), 0, 0, ms);
}

/**
 * Windows can briefly lock the target while an indexer or antivirus reads it,
 * which surfaces as EPERM/EBUSY. Retrying beats deleting the good file first.
 */
function renameWithRetry(from, to) {
  for (let attempt = 0; attempt < 5; attempt += 1) {
    try {
      fs.renameSync(from, to);
      return;
    } catch (error) {
      const retryable = error.code === 'EPERM' || error.code === 'EBUSY' || error.code === 'EACCES';
      if (!retryable || attempt === 4) throw error;
      sleepSync(20);
    }
  }
}

/**
 * Write to a temporary file in the same directory, flush it, then rename. A
 * crash mid-write leaves either the old file or no file, never half a vault.
 */
function writeFileAtomic(target, contents) {
  const directory = path.dirname(target);
  const temporary = path.join(
    directory,
    `.${path.basename(target)}.${process.pid}.${Date.now()}.tmp`
  );

  try {
    fs.mkdirSync(directory, { recursive: true });
  } catch {
    throw new StorageError('write_failed');
  }

  let fd;
  try {
    fd = fs.openSync(temporary, 'wx', 0o600);
    fs.writeFileSync(fd, contents, 'utf8');
    fs.fsyncSync(fd);
  } catch {
    if (fd !== undefined) {
      try {
        fs.closeSync(fd);
      } catch {}
    }
    try {
      fs.rmSync(temporary, { force: true });
    } catch {}
    throw new StorageError('write_failed');
  }

  try {
    fs.closeSync(fd);
  } catch {
    throw new StorageError('write_failed');
  }

  try {
    renameWithRetry(temporary, target);
  } catch {
    try {
      fs.rmSync(temporary, { force: true });
    } catch {}
    throw new StorageError('write_failed');
  }
}

function readFileIfExists(target) {
  try {
    return fs.readFileSync(target, 'utf8');
  } catch (error) {
    if (error.code === 'ENOENT') return null;
    throw new StorageError('read_failed');
  }
}

function removeFile(target) {
  try {
    fs.rmSync(target, { force: true });
  } catch {
    throw new StorageError('write_failed');
  }
}

function listChangeLogs(syncDir) {
  let names;

  try {
    names = fs.readdirSync(syncDir);
  } catch (error) {
    if (error.code === 'ENOENT') return [];
    throw new StorageError('read_failed');
  }

  const logs = [];
  for (const name of names) {
    const match = CHANGE_LOG_PATTERN.exec(name);
    if (match) logs.push({ deviceId: match[1], fileName: name });
  }

  return logs;
}

function defaultSettings() {
  return { syncFolder: null };
}

/**
 * A damaged settings file must not lock the user out: the worst case is that
 * the sync folder is asked for again.
 */
function readSettings(dataDir) {
  let raw;

  try {
    raw = readFileIfExists(settingsPath(dataDir));
  } catch {
    return defaultSettings();
  }

  if (!raw) return defaultSettings();

  try {
    const parsed = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null) return defaultSettings();
    return { syncFolder: typeof parsed.syncFolder === 'string' ? parsed.syncFolder : null };
  } catch {
    return defaultSettings();
  }
}

function writeSettings(dataDir, settings) {
  const safe = {
    syncFolder: typeof settings?.syncFolder === 'string' ? settings.syncFolder : null,
  };
  writeFileAtomic(settingsPath(dataDir), JSON.stringify(safe, null, 2));
}

module.exports = {
  MAX_STORED_BYTES,
  StorageError,
  vaultPath,
  settingsPath,
  syncLogPath,
  assertDeviceId,
  assertPayload,
  writeFileAtomic,
  readFileIfExists,
  removeFile,
  listChangeLogs,
  readSettings,
  writeSettings,
};
